import java.util.*;

class Solution {
  public int longestValidSubstring(String word, List<String> forbidden) {
    int total = 1;
    for (String f : forbidden) total += f.length();
    int[] next = new int[total * 26];
    boolean[] end = new boolean[total];
    int nodes = 1;
    for (String f : forbidden) {
      int cur = 0;
      for (int i = f.length() - 1; i >= 0; i--) {
        int c = f.charAt(i) - 'a';
        if (next[cur * 26 + c] == 0) next[cur * 26 + c] = nodes++;
        cur = next[cur * 26 + c];
      }
      end[cur] = true;
    }
    int n = word.length(), left = 0, best = 0;
    for (int r = 0; r < n; r++) {
      int cur = 0;
      for (int k = r; k >= Math.max(left, r - 9); k--) {
        cur = next[cur * 26 + word.charAt(k) - 'a'];
        if (cur == 0) break;
        if (end[cur]) {
          left = k + 1;
          break;
        }
      }
      best = Math.max(best, r - left + 1);
    }
    return best;
  }
}
